def q(question: str, answer: str, *wrong: str) -> dict:
    opts = [answer, *wrong]
    while len(opts) < 4:
        opts.append(f"Option {len(opts)+1}")
    opts = opts[:4]
    # stable shuffle by question text
    rng = random.Random(hash(question) & 0xFFFFFFFF)
    rng.shuffle(opts)
    if answer not in opts:
        opts[0] = answer
    return {"question": question, "answer": answer, "options": opts}


