    # Fix a couple awkward keys
    out = banks.get(level, banks[8])[:]
    # clean any overly long meta answers
    cleaned = []
    for item in out:
        ans = item["answer"]
        if " — " in ans:
            ans = ans.split(" — ")[0].strip()
        if len(ans) > 60:
            ans = ans[:60]
        opts = []
        for o in item["options"]:
            if " — " in o:
                o = o.split(" — ")[0].strip()
            opts.append(o)
        if ans not in opts:
            opts[0] = ans
        cleaned.append({"question": item["question"], "answer": ans, "options": opts})
    return cleaned


